    """Parse a single CSV line into fields.
    Handles optional double quotes. Inside quoted fields, commas are literal and "" represents a single quote.
    Empty string returns [''].
    """
    if line == "":
        return [""]
    fields = []
    field_chars = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i+1] == '"':
                    field_chars.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field_chars.append(ch)
                i += 1
        else:
            if ch == '"':
                in_quotes = True
                i += 1
            elif ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
                i += 1
            else:
                field_chars.append(ch)
                i += 1
    # Append last field (including case of trailing comma resulting in empty field)
    fields.append(''.join(field_chars))
    return fields
