def solve(matrix):
    # Compute determinant using Bareiss algorithm for exact integer arithmetic.
    n = len(matrix)
    if n == 0:
        return 1
    # Make a copy to avoid mutating input
    a = [row[:] for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Pivot: if zero, swap with a lower row
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        prev_pivot = a[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev_pivot
        # Zero out the column below pivot (optional for clarity)
        for i in range(k + 1, n):
            a[i][k] = 0
    return sign * a[n - 1][n - 1]

