def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer (including negative) or one of '+', '-', '*', '/'.
    Division truncates toward zero. If division by zero occurs, treat the result as 0.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            # Assuming well‑formed RPN: there are at least two operands on the stack
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                if b == 0:
                    # Define division by zero result as 0 to avoid exception
                    stack.append(0)
                else:
                    # Truncate toward zero
                    sign = -1 if (a < 0) ^ (b < 0) else 1
                    stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(token))
    # If no result, return 0
    return stack[0] if stack else 0

def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Uses sliding window with dict of last index.
    """
    last_index = {}
    max_len = 0
    start = 0  # left boundary of window
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            # character repeated, move start right after previous occurrence
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

